package com.bank.reporting;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class KthLargestDemo {

    private static final Logger log = Logger.getLogger(KthLargestDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TopTransactions service = new TopTransactions();

        BigDecimal[] amounts = {
                new BigDecimal("1200"), new BigDecimal("50000"), new BigDecimal("300"),
                new BigDecimal("98000"), new BigDecimal("7500"), new BigDecimal("25000")
        };

        BigDecimal third = service.kthLargest(amounts, 3);
        log.info(() -> "3rd largest transaction: " + third);  // 25000
    }
}

