class TopTransactions {

    private static final Logger log = Logger.getLogger(TopTransactions.class.getName());

    BigDecimal kthLargest(BigDecimal[] amounts, int k) {
        // Min-heap (natural order) keeping only the k largest seen so far.
        java.util.PriorityQueue<BigDecimal> heap = new java.util.PriorityQueue<>();
        for (BigDecimal amount : amounts) {
            heap.offer(amount);
            if (heap.size() > k) {
                BigDecimal evicted = heap.poll();   // drop current smallest
                log.fine(() -> "  evicted " + evicted + " (outside top " + k + ")");
            }
        }
        return heap.peek();                         // smallest of top k = kth largest
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
